"""Publication-only renderer. Frozen audited medians -> SVGs and matching HTML tables."""
from pathlib import Path
import json, math, html, hashlib, sys, subprocess
L=Path(__file__).resolve().parents[1]; A=L/'public/benchmarks/filesystem-automation/assets'
E=['nift','python','node','bun','go']; C=['#b1ff68','#ffbd9a','#d2b4ef','#e9dc91','#88cdb5']; S={}
d=json.loads((L/'content/benchmarks/filesystem-automation/published.json').read_text());meta=d['meta']
assert len(d['cells'])==376 and len(meta['evidence_sha'])==40
for x in d['cells']:S[x['scenario'],x['boundary'],x['engine']]=x
mem={(x['files'],x['engine']):x for x in d['memory_accounting']};assert len(mem)==15
evidence='https://github.com/nift-experiments/lab-evidence/tree/'+meta['evidence_sha']+'/benchmarks/filesystem-automation/'+meta['series']
sections=[]; plots=[]
def esc(x): return html.escape(str(x))
def panel(id,title,keys,labels,note,unit='ms',memory=False,line=False):
 vals=[[mem[int(k),e]['process_maxrss_mib'] if memory else S.get((k,'booted',e),{}).get('wall_ms',{}).get('median') for e in E] for k in keys]
 sections.append(dict(id=id,title=title,unit=unit,labels=labels,values=vals,scenarios=keys,note=note))
 # All comparisons use explicit logarithmic axes, except diagnostic memory (linear).
 log=not memory; high=max(v for row in vals for v in row if v is not None); low=min(v for row in vals for v in row if v is not None)
 lo=10**math.floor(math.log10(low)) if log else 0; hi=10**math.ceil(math.log10(high)) if log else math.ceil(high/50)*50
 def y(v): return 350-(math.log10(v/lo)/math.log10(hi/lo) if log else v/hi)*260
 svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 840 440" role="img" aria-labelledby="title desc">',f'<title id="title">Nift v4.12 final · {esc(title)}</title><desc id="desc">{esc(note)}. Exact values in the adjacent table. '+('Logarithmic' if log else 'Linear zero-origin')+' vertical axis.</desc>','<rect width="840" height="440" fill="#202622" rx="12"/>',f'<text x="70" y="30" fill="#c3cdc4" font-family="sans-serif" font-size="13">Nift v4.12 final · {unit} · '+('LOGARITHMIC SCALE' if log else 'LINEAR SCALE')+'</text>']
 ticks=[10**i for i in range(int(math.log10(lo)),int(math.log10(hi))+1)] if log else list(range(0,int(hi)+1,50))
 for t in ticks:
  yy=y(t); svg.append(f'<path d="M70 {yy}H805" stroke="#3b463d"/><text x="58" y="{yy+4}" text-anchor="end" fill="#b6c0b7" font-family="sans-serif" font-size="12">{t:g}</text>')
 xs=[100+i*660/max(1,len(keys)-1) for i in range(len(keys))] if line else [110+i*680/len(keys) for i in range(len(keys))]
 for j,e in enumerate(E):
  points=[]
  for i,row in enumerate(vals):
   v=row[j]
   if v is None: continue
   xx=xs[i] if line else xs[i]+j*min(22,110/len(keys)); yy=y(v); points.append(f'{xx},{yy}')
   if line: svg.append(f'<circle cx="{xx}" cy="{yy}" r="4.5" fill="{C[j]}"/>')
   else: svg.append(f'<path d="M{xx} 350V{yy}" stroke="{C[j]}" stroke-width="{min(14,72/len(keys))}"/><circle cx="{xx}" cy="{yy}" r="3" fill="{C[j]}"/>')
  if line: svg.append(f'<polyline points="{" ".join(points)}" fill="none" stroke="{C[j]}" stroke-width="2.5"/>')
  xx=80+j*150; svg.append(f'<circle cx="{xx}" cy="410" r="4" fill="{C[j]}"/><text x="{xx+12}" y="414" fill="{C[j]}" font-family="sans-serif" font-size="14">{('Nift v4.12 final' if e=='nift' else e.title())}</text>')
 for i,label in enumerate(labels): svg.append(f'<text x="{xs[i] if line else xs[i]+40}" y="377" text-anchor="middle" fill="#dce4dd" font-family="sans-serif" font-size="12">{esc(label)}</text>')
 svg.append('</svg>'); (A/f'{id}.svg').write_text('\n'.join(svg)+'\n'); plots.append(id)
 table=f'<div class="scroll" tabindex="0" role="region" aria-label="{esc(title)} exact values"><table><caption>{esc(title)} · '+('raw wait4 peak median / full child lifetime, unranked inherited-floor accounting' if memory else 'booted isolated request, median')+f' · {unit}</caption><thead><tr><th>Workload</th>'+''.join(f'<th>{e.title()}</th>' for e in E)+'</tr></thead><tbody>'
 for label,row in zip(labels,vals): table+='<tr><th>'+esc(label)+'</th>'+''.join('<td>'+('—' if v is None else f'{v:,.3f}')+'</td>' for v in row)+'</tr>'
 table+='</tbody></table></div>'
 return f'<div class="measurement"><figure><div class="chart-scroll" tabindex="0" role="region" aria-label="Scrollable graph"><img src="@path(\'public/benchmarks/filesystem-automation/assets/{id}.svg\')" alt="{esc(title)}" width="840" height="440"></div><figcaption>{esc(note)} '+('Linear zero-origin axis.' if memory else 'Logarithmic axis; equal vertical steps represent multiplicative changes.' + ('' if line else ' Bars start at the displayed positive minimum, not zero.'))+f' <a href="@path(\'public/benchmarks/filesystem-automation/assets/{id}.svg\')">SVG ↗</a></figcaption></figure>{table}<p class="scroll-hint">Exact values above. On small screens, scroll the table independently →</p></div>'
parts=[]
def sec(id,num,title,lede,body): parts.append(f'<section id="{id}" class="inspection"><div class="section-label"><span>{num}</span><code>project/{id}/</code></div><div class="section-body"><h2>{title}</h2><p class="lede">{lede}</p>{body}</div></section>')
def final_gap(case):
 rows=[S[case,'booted',e] for e in E];n=rows[0];p=min(rows[1:],key=lambda x:x['wall_ms']['median']);v=n['wall_ms']['median'];w=p['wall_ms']['median'];return gap(f'{v/w:.1f}×',f'Final candidate: Nift {v:,.3f} ms versus {p["engine"].title()} {w:,.3f} ms. Exact audited {case} contract on this node.')
def gap(ratio,description): return f'<aside class="finding"><strong>{ratio}</strong><p>{description}</p></aside>'
sec('walk','01','Follow every path.','A directory walk becomes a runtime workload long before it becomes a bandwidth test.',final_gap('walk-10000')+panel('walk','Traversal scaling',[f'walk-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Five runtimes enumerate the same three-level fixture and return a verified path inventory',line=True))
sec('inspect','02','Metadata has a cost.','Type-only checks acquire size metadata too. The explicit stat workload adds two queries per file.',final_gap('stat-10000')+panel('stat','Metadata scaling',[f'stat-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Exists/type/size inspection, with checked metadata inventories',line=True)+'''<div class="syscalls"><h3>Historical metadata trace / 20261011</h3><div><span>Logical files</span><b>10,000</b><i style="width:24.17%"></i></div><div><span>Walk: newfstatat</span><b>21,373</b><i style="width:51.66%"></i></div><div><span>Stat: newfstatat</span><b>41,373</b><i style="width:100%"></i></div><p>Historical release trace, not final-candidate syscall measurements; linear zero-origin counts. Counts include directory/runtime work. Only four readlinks per trace. Syscall counts do not explain all wall time.</p></div>''')
sec('select','03','Inspect first. Select second.','Every filter stats every file before selection. Selection percentages describe results, not avoided metadata work.',panel('select','Filtering / 10k files',['filter-1-10000','filter-10-10000','filter-50-10000','filter-extension-10000','filter-prefix-10000','filter-size-10000'],['Name 1%','Name 10%','Name 50%','Extension','Prefix','Size'],'Extension .md selects 20%; group00 prefix 5%; size ≥768 bytes 40%. Extension/group/size are correlated'))
sec('read','04','Small files expose scalar work.','The checksum visits every byte in the language. Large-file reads load the full payload but aggregate endpoints only.',final_gap('read-10000')+panel('read','Small-file read + checksum',[f'read-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Portable h=(31h+byte)%1000000007 checksum; noncryptographic; output inventories included',line=True)+panel('large-read','100 MiB bulk-read contrast',['large-read-10x10485760','large-read-100x1048576'],['10 × 10 MiB','100 × 1 MiB'],'These different contracts isolate a bulk-read contrast, not a subtraction-based estimate of checksum cost'))
sec('fingerprint','05','A fingerprint is not a security digest.','Native SHA-256 is unavailable in this Nift snapshot. The portable checksum cannot substitute for a cryptographic release manifest.',panel('hash','Native SHA-256 / 10k files',['hash-sha256-10000'],['SHA-256'],'— means unavailable; it is not zero or a failed observation'))
sec('write','06','Create. Overwrite. Copy.','Stream writes include source reads; copies verify bytes and paths, not permissions or metadata.',final_gap('copy-100000')+panel('write','Write and copy',['write-10000','overwrite-10000','large-write-10x10485760','large-write-100x1048576','copy-100000'],['Create 10k','Overwrite 10k','10 × 10 MiB','100 × 1 MiB','Copy 100k'],'Small stream writes, existing-file overwrite, 100 MiB streams, and a 100k-file copy are distinct contracts'))
sec('mirror','07','Unchanged still means inspected.','Both trees are fingerprinted. Identical destination files retain their timestamps.',final_gap('mirror-0-10000')+'''<div class="diff"><div><h3>source/</h3><code>  keep.md <span>unchanged</span><br>~ edit.md <span>new bytes</span><br>+ add.dat <span>new path</span></code></div><div><h3>destination/ → reconciled</h3><code>  keep.md <span>preserve mtime</span><br>~ edit.md <span>replace bytes</span><br>+ add.dat <span>copy</span><br>- old.dat <span>remove</span></code></div></div>'''+panel('mirror','Mirror / 10k files',[f'mirror-{v}-10000' for v in [0,1,10,11,12]],['Clean','1% content','10% content','Mixed','Add/delete'],'Mixed =10% content +1% add/delete; add/delete-only =1% replacement paths. Diagram illustrates semantics, not a measured individual filename'))
sec('changes','08','What changed depends on the contract.','Modification-time access is unavailable in this Nift snapshot. Content and timestamp detection intentionally answer different questions.',panel('changes','Change detection / 10k files',[f'detect-{kind}-{v}-10000' for kind in ['mtime','hash'] for v in [1,2,3]],['Time: bytes','Time: time','Time: restored','Hash: bytes','Hash: time','Hash: restored'],'Same 1% selected set: changed bytes/new time; same bytes/new time; changed bytes/restored time. Time-only detection misses restored-time edits; content ignores time-only edits'))
sec('pipeline','09','The project, end to end.','Generate documents, copy selected assets and produce a sorted manifest. This is controlled project automation, not a website build.',final_gap('mixed-10000')+panel('pipeline','Project workflows / 10k files',['manifest-10000','generate-10000','mixed-10000'],['Manifest','Generate','Mixed'],'Manifest =path/size/portable fingerprint; generate prefixes inputs; mixed ignores group19, generates .md and copies .dat. Traversal still visits ignored paths'))
sec('memory','10','Inspect recorded memory. Keep the scope.','Unranked wait4 peak accounting from current final-candidate walk observations; not a runtime memory-efficiency comparison.',panel('memory-accounting','Unranked wait4 peak accounting',['1000','10000','100000'],['1k files','10k files','100k files'],'Current median maximum-child RSS across the full invocation, even for booted wall timing. Inherited supervisor-image floors can dominate. This is not post-exec VmHWM, private memory or memory per file',unit='MiB',memory=True,line=True)+'<p>The final noop-child control rose from 16.75 to 80.75 MiB when the parent allocated 64 MiB, despite doing no runtime workload. No final-candidate post-exec walk cohort was measured: the earlier post-exec metric cannot be reproduced from these samples. This replacement exposes the recorded final-only accounting with its different boundary; it must not rank runtimes. Raw RSS remains unchanged and no constant is subtracted.</p>')
# Original post-exec SVG is a preserved immutable asset; final raw wait4 is a different metric.
historical=d['historical_memory'];assert historical['pass']
assert hashlib.sha256((A/'memory.svg').read_bytes()).hexdigest()==d['historical_memory_svg_sha256']
H={(x['files'],x['engine']):x['postexec_vmhwm_mib'] for x in historical['rows']}
values=[[H[n,e] for e in E] for n in [1000,10000,100000]]
sections.append({'id':'memory','title':'Historical 20261011 post-exec walk high-water mark','unit':'MiB','labels':['1k files','10k files','100k files'],'values':values,'scenarios':['1000','10000','100000'],'note':'Historical 20261011 post-exec VmHWM; exact source445f4d; separate from current final wait4 accounting','cohort':'20261011-v4110','historical':True})
t='<div class="scroll" tabindex="0"><table><caption>Historical 20261011 post-exec VmHWM, MiB; one verified request per cell</caption><thead><tr><th>Files</th>'+''.join('<th>'+e.title()+'</th>' for e in E)+'</tr></thead><tbody>'
for n,row in zip([1000,10000,100000],values):t+='<tr><th>'+f'{n:,}'+'</th>'+''.join('<td>'+f'{v:,.3f}'+'</td>' for v in row)+'</tr>'
t+='</tbody></table></div>'
sec('historical-memory','10b','Preserved post-exec memory view.','Historical 20261011 Nift4.11 snapshot and pinned peers; this is not final-v4.12 memory.', '<div class="measurement"><figure><div class="chart-scroll" tabindex="0"><img src="@path(\'public/benchmarks/filesystem-automation/assets/memory.svg\')" width="840" height="440" alt="Historical 20261011 post-exec walk high-water mark"></div><figcaption>Original post-exec VmHWM graph, preserved unchanged. One verified request per cell; not an official distribution or current final result. <a href="@path(\'public/benchmarks/filesystem-automation/assets/memory.svg\')">SVG ↗</a></figcaption></figure>'+t+'</div>')
plots.append('memory')
sec('diagnostics','11','Current strengths. Visible gaps.','Final v4.12 exact-output gates and measured peer boundaries.', '<div class="priorities"><article><small>METADATA / EXACT OUTPUT</small><h3>Walk, inspect and select.</h3><p>All path inventories and selected metadata rows pass exact oracles. Current scaling and peer costs remain in the graphs above.</p></article><article><small>BULK / REMAINING GAP</small><h3>Checksum loops remain expensive.</h3><p>Portable checksum/content detection reaches a 49.89× wall deficit against Go. Metadata throughput does not remove per-byte evaluator cost.</p></article><article><small>NATIVE API / UNAVAILABLE</small><h3>Keep capability gaps explicit.</h3><p>Native SHA-256, stat timestamps and recursive directory removal are not supported by the certified Nift adapter boundary.</p></article><article><small>CORRECTNESS GATE / PASS</small><h3>One call means one call.</h3><p>Final inline and bound execute reductions run exactly once. Every accepted mutation and output set is independently checked.</p></article></div>')
sec('retained-gain-controls','11b','Separate same-node source controls.','Historical releasec8d / checkpoint7f / finalc14; three observations per version, not official peer distributions.', '<div class="priorities"><article><small>STAT / 10K</small><h3>3,526.405 → 324.338 ms</h3><p>Release to final:90.80% lower. Checkpoint319.135 ms; final +1.63% descriptive increase, no significance claim.</p></article><article><small>SIZE FILTER / 10K</small><h3>2,812.878 → 321.283 ms</h3><p>Release to final:88.58% lower; every file statted before selection.</p></article><article><small>WALK / 10K</small><h3>1,629.322 → 211.441 ms</h3><p>Release to final:87.02% lower; exact inventory. This diagnostic does not replace current peer charts.</p></article></div>')
sec('practitioner','12','Which tool would I choose?','AI-DX is an independent axis; useful explicitness does not imply a universal throughput win.', '<p><strong>Human + agent:</strong> Python for a new general filesystem script; Go for throughput-heavy bulk processing; Nift for bounded artifact operations already in a Nift project. <strong>Agent-primary:</strong> Nift for that bounded existing-project workflow, Python for new standalone general policy, Go for bulk work.</p><p>Explicit inputs, output ownership, order, invalidation and lifecycle can make agent edits easier to verify. That is a design judgment: comparative autonomous authoring success and repair costs were not measured. Helpers should remove duplicated synchronization while preserving these separate semantics.</p><p>Observed contracts: exact outputs and mutation/reset state across all accepted cells; five edge-path oracles; missing-directory error; inline/bound execution once. Harness JSON is not product-native structured feedback. Partial mutation rollback, arbitrary symlink/security handling and automatic recovery were not evaluated. Do not mistake external reset/oracle checks for transactional product safety.</p><p>Native SHA-256, stat timestamps and recursive directory deletion remain gaps. Portable checksums and external helpers are different contracts. AI-DX does not override the large bulk throughput deficits shown above.</p>')
sec('method','13','Frozen evidence. Open interpretation.','Audited final-candidate refresh with preserved graph designs.',f'''<p>{esc(meta['machine'])} Four-CPU affinity. {esc(meta['counts'])}</p><p>Candidate source: <a href="https://github.com/nift-dev/nift/tree/{meta['candidate_sha']}"><code>{meta['candidate_sha']}</code></a>.</p><p>Fresh timing includes launch and exit; booted timing begins after readiness and ends at the complete response. Every observation uses a new runtime. Fixtures are restored, fully read and statted outside timing. Runtime order rotates; no outliers are removed. Full result sets/output SHA-256 checks and independent distribution/reset audits pass. Low-count stress tails are descriptive.</p><p>Warm Linux filesystem state, ASCII paths, fixed three-level corpus, no symlink/permission/glob or physical-bandwidth claim. Five file sizes (96–2,048 bytes) and extensions correlate with groups. No fsync or global cache dropping. Output serialization is inside timing; canonical oracle sorting is outside (Nift ls itself sorts).</p><details><summary>Frozen identities / timing tails / implementation boundaries</summary><p>Primary <code>75e77bb4bb6fb0b8c49920f641c77b394aec5985</code>; supplement <code>1ab31488eb949eb8f8cd6d50b0eb9fd59e1ad78e</code>; core <code>c14d06835bca515a5281e41da0e40219c2d60ef0</code>. Evidence commit <code>{meta['evidence_sha']}</code>.</p><p>All 752 distributions, p95/min/max, commands, source, correctness and implementation boundaries remain in the evidence and full appendix. The launch/lifetime memory accounting limitation is preserved alongside the corrected diagnostic.</p></details><p><a href="{evidence}">Canonical frozen evidence ↗</a> · <a href="{evidence}/primary/summary.json">Audited complete distributions ↗</a> · <a href="{evidence}/AI-DX-ASSESSMENT.json">AI-DX assessment / evidence boundaries ↗</a></p>''')
parts.append('<p><a href="@path(\'benchmarks/filesystem-automation/series/20261011-v4110/\')">Preserved original report and analytical views ↗</a></p>')
hero='''<main id="main"><header class="hero"><div class="hero-copy"><p class="eyebrow">EXPERIMENT 08 / FILESYSTEM AUTOMATION</p><h1>Every file.<br>Every consequence.</h1><p class="intro">A project tree under inspection.<br>Five runtimes. One verified filesystem.</p><p class="hero-verdict">Nift completes the work.<br><strong>Bulk checksum and mirror throughput still lag.</strong></p><a class="open" href="#walk">Inspect the findings ↓</a></div><div class="inspector"><div class="window-bar"><span>◉ project/</span><span>READ · VERIFY · RECONCILE</span></div><div class="tree-map"><div class="folder">▾ project/</div><div class="branch">▾ group00/ … group19/<div class="branch">▾ depth0/ … depth2/<div class="branch">▾ bucket000/<p><code>f000000.md</code><em>GENERATE</em></p><p><code>f000001.json</code><em>INSPECT</em></p><p><code>f000004.dat</code><em>COPY</em></p></div></div></div><div class="manifest">↳ output/manifest.tsv <span>✓ VERIFIED</span></div></div><div class="density"><span>1,000</span><i>→</i><span>10,000</span><i>→</i><span>100,000 files</span></div></div></header><div class="pipeline-trail" aria-label="Workload pipeline"><span>SCAN</span>→<span>INSPECT</span>→<span>SELECT</span>→<span>READ</span>→<span>HASH</span>→<span>TRANSFORM</span>→<span>WRITE</span></div><p class="participants">Nift 4.12.0 final candidate · Python 3.15.0 · Node 24.21.0 · Bun 1.4.3 · Go 1.27.2</p><nav class="index" aria-label="Report sections">'''+''.join(f'<a href="#{id}">{title}</a>' for id,title in [('walk','walk'),('inspect','inspect'),('select','select'),('read','read'),('mirror','mirror'),('pipeline','pipeline'),('memory','memory'),('diagnostics','diagnostics'),('practitioner','verdict')])+ '</nav>'
(L/'content/benchmarks/filesystem-automation/index.html').write_text(hero+'\n'.join(parts)+'</main>\n')
(A/'published.json').write_text(json.dumps({'meta':meta,'sections':sections},separators=(',',':'))+'\n')
print(f'{len(plots)} SVG charts; {sum(len(s["values"]) for s in sections)} exact-value rows')

for slug in plots:
 subprocess.run(['inkscape',str(A/(slug+'.svg')),'--export-type=png','--export-dpi=150'],check=True,capture_output=True)
